func _continue_game() -> void:
	if not m.has_saved_game:
		return
	_dismiss_menu()
	# Preserve an explicitly active Day One save on Continue. Saves from before
	# the Day One namespace still take the legacy direct-game route.
	var continue_day_one: bool = continue_day_one_mode(m.save_data)
	m._launch_from_start_menu(continue_day_one)
	if m.chime != null:
		m.chime.pitch_scale = 1.0
		m.chime.play()

func _perform_new_game() -> void:
	if not m._start_new_game():
		return
	m.get_tree().root.set_meta(DAY_ONE_AFTER_RESET_META, true)
	m.get_tree().call_deferred("reload_current_scene")

func _launch_from_start_menu(start_day_one: bool) -> void:
	# The launch choice owns the Day 1 boundary. Continue is deliberately a
	# direct game entry, even when an older save predates the Day 1 fields;
	# New Game keeps the fresh-save defaults and fires the authored arrival.
	_prepare_start_menu_launch(start_day_one)
	if START_AT_CASTLE_GATE:
		var director: DayOneDirector = _day_one_ref()
		if start_day_one and director.dirty_castle_discovered:
			# Establish the Canvas world first (game = "level2"), exactly as the
			# boss return does. Without it the empty-world watchdog re-resumed the
			# room every frame and the room's activity never mounted.
			_enter_level2_now(true)
			_enter_castle_interior_now()
			var resume_room: String = day_one_castle_room_for_current()
			if _castle_rooms_ref().is_open():
				_castle_rooms_ref().show_room(resume_room, false)
		else:
			_enter_level2_now(false, false, true)

func _tick_target_affordances(focus_id: String, focus_t: float) -> void:
	for value: Variant in m.g.get("lagoon_promenade_targets", []) as Array:
		var target: Dictionary = value as Dictionary
		var glow: Sprite2D = target.get("highlight") as Sprite2D
		if glow == null or not is_instance_valid(glow):
			continue
		var selected: bool = String(target.get("id", "")) == focus_id
		glow.visible = true
		var kind: String = String(target.get("affordance_kind", Affordance.INTERACTION))
		var wave: float = sin(focus_t * Affordance.pulse_speed(kind, selected))
		var tint: Color = Affordance.color(kind, selected)
		if selected:
			tint.a = lerpf(0.82, 1.0, wave * 0.5 + 0.5)
		else:
			# Day One's castle gate is the route anchor. It must remain a readable
			# idle cue after focus is cleared; the generic promenade cap would make
			# the only safe destination effectively disappear.
			if m.day_one_is_active() and String(target.get("id", "")) == "castle_gate":
				tint.a = maxf(tint.a, 0.45)
			else:
				tint.a = minf(tint.a, 0.055)
		glow.modulate = tint
		var pulse: float = 1.0 + wave * Affordance.pulse_amount(kind, selected)
		var base_scale: float = float(target.get("highlight_scale", 1.0))
		if String(glow.get_meta("focus_cue_role", "")) \
				== "procedural_ring_pointer":
			glow.scale = Vector2.ONE * base_scale * pulse
		elif String(target.get("id", "")) != "castle_gate":
			var node: Node2D = target.get("node") as Node2D
			if node is Sprite2D:
				glow.scale = (node as Sprite2D).scale * base_scale * pulse

static func color(kind: String, focused: bool) -> Color:
	var normalized: String = normalize(kind)
	if normalized == ANIMATION:
		return GOLD_FOCUS if focused else GOLD_IDLE
	if normalized == PLOT:
		return RED_FOCUS if focused else RED_IDLE
	return BLUE_FOCUS if focused else BLUE_IDLE
